export const passengerLocales = [
  { code: "zh-CN", short: "CN", label: "简体中文" },
  { code: "zh-TW", short: "繁", label: "繁體中文" },
  { code: "ja", short: "JP", label: "日本語" },
  { code: "en", short: "EN", label: "English" },
  { code: "vi", short: "VI", label: "Tiếng Việt" },
  { code: "ne", short: "NP", label: "नेपाली" },
  { code: "ko", short: "KR", label: "한국어" },
  { code: "es", short: "ES", label: "Español" },
] as const;

export type PassengerLocale = (typeof passengerLocales)[number]["code"];

export function normalizePassengerLocale(value: string): PassengerLocale | null {
  const code = value.trim().toLowerCase();
  if (code.startsWith("zh-tw") || code.startsWith("zh-hk") || code.startsWith("zh-hant")) return "zh-TW";
  if (code.startsWith("zh")) return "zh-CN";
  if (code.startsWith("ja")) return "ja";
  if (code.startsWith("en")) return "en";
  if (code.startsWith("vi")) return "vi";
  if (code.startsWith("ne")) return "ne";
  if (code.startsWith("ko")) return "ko";
  if (code.startsWith("es")) return "es";
  return null;
}

